const paths={radar:'M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5M12 12l8-8M16 3h5v5',files:'M8 3H4v14h3M10 7h10v14H10zM13 11h4M13 15h4',bookmark:'M6 3h12v18l-6-4-6 4V3Z',wallet:'M20 8V5H4a2 2 0 0 0 0 4h17v11H4a2 2 0 0 1-2-2V7M21 12h-6v4h6M17 14h.01',book:'M3 3h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3V3Zm9 2v16',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',sun:'M12 3V1m0 22v-2m9-9h2M1 12h2m15.4-6.4 1.4-1.4M4.2 19.8l1.4-1.4m12.8 0 1.4 1.4M4.2 4.2l1.4 1.4M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',moon:'M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z',arrow:'M5 12h14m-6-6 6 6-6 6',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',lock:'M5 10h14v11H5V10Zm3 0V7a4 4 0 0 1 8 0v3m-4 5v2',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 10 3 3 5-6',check:'m5 12 4 4L19 6',circlecheck:'M22 11v1a10 10 0 1 1-6-9M8 11l4 4L22 5',activity:'M3 12h4l3-9 4 18 3-9h4',chart:'M4 3v18h17M8 16l4-5 4 3 5-8',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',refresh:'M20 8a9 9 0 1 0 .5 8M20 3v6h-6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 11h18',code:'m8 7-5 5 5 5M16 7l5 5-5 5m-3-14-2 18',menu:'M3 6h18M3 12h18M3 18h18',x:'m6 6 12 12M6 18 18 6',copy:'M8 8h13v13H8zM16 8V3H3v13h5',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',warning:'m12 3 10 18H2L12 3Zm0 6v5m0 3h.01',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c6 6 6 14 0 20-6-6-6-14 0-20Z',bolt:'m13 2-9 12h7l-1 8 10-13h-7l0-7Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function read(key,fallback){try{const raw=localStorage.getItem('proofbundles.'+key);return raw===null?fallback:JSON.parse(raw)??fallback;}catch{return fallback;}}
const storage={checks:read('checks',[]),watch:read('watch',[]),theme:read('theme','dark'),density:read('density','comfortable'),bundleSnapshots:read('bundleSnapshots',[])};
storage.checks=Array.isArray(storage.checks)?storage.checks.filter(r=>r&&validAddress(r.address)&&r.token&&r.assessment&&Array.isArray(r.assessment.checks)&&Number.isFinite(Date.parse(r.at))).slice(0,100):[];
storage.watch=Array.isArray(storage.watch)?storage.watch.filter(t=>t&&validAddress(t.address)).slice(0,90):[];
storage.bundleSnapshots=Array.isArray(storage.bundleSnapshots)?storage.bundleSnapshots.filter(validBundleSnapshot).slice(0,40):[];
let bundleViewMint='';const bundleAnchorDrafts=new Map();
let bundleViewState={tab:'overview',owner:'',query:'',compare:false},activeBundleRequest=null;
let backendConfig=null,holderState={wallet:null,pro:false};const bundleEvidence=new Map();for(const r of storage.bundleSnapshots)if(!bundleEvidence.has(r.mint))bundleEvidence.set(r.mint,r);
let market=[],marketError='',marketTime=null,marketLoading=false,activeMarket='all',view='grid',wallet=null,walletProvider=null,balance=null,renderEpoch=0,reportPending=new Set(),modalTrigger=null,closeListener=null;
const reports=new Map(storage.checks.map(r=>[r.address,r]));
function persist(key,value){storage[key]=value;try{localStorage.setItem('proofbundles.'+key,JSON.stringify(value));}catch{toast('Browser storage is full or unavailable. Export your research to keep a copy.');}updateCounts();}
function updateCounts(){$('#checks-count').textContent=storage.checks.length;$('#watch-count').textContent=storage.watch.length;}
function applySettings(){document.documentElement.dataset.theme=storage.theme;document.body.classList.toggle('compact',storage.density==='compact');$('#theme-toggle').innerHTML=icon(storage.theme==='dark'?'sun':'moon');}applySettings();
$$('[data-icon]').forEach(el=>el.tagName==='A'?el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon)):el.innerHTML=icon(el.dataset.icon));$('#copyright-year').textContent=new Date().getFullYear();
function toast(message){const el=document.createElement('div');el.className='toast';el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),4500);}
function route(){const value=location.hash.slice(1)||'/';return value.startsWith('/')?value:'/';}
function navigate(value){if(route()===value)render();else location.hash=value;}
function intro(title,description,action=''){return `<div class="page-intro"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action||`<div class="date-label">${icon('calendar')}${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}).toUpperCase()}</div>`}</div>`;}
function updateNavigation(){
 const r=route();
 $$('[data-route]').forEach(a=>{const active=a.dataset.route===r||(r.startsWith('/report/')&&a.dataset.route==='/checks');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 updateCounts();updateWalletLabel();
}
function updateWalletLabel(){ $('#wallet-label').textContent=wallet?short(wallet):'Connect wallet'; }
function scanForm(){return `<div class="scan-box"><form class="scan-form" id="scan-form">${icon('search')}<label class="sr-only" for="scan-input">Project website, name, ticker or Solana mint address</label><input id="scan-input" name="query" autocomplete="off" spellcheck="false" required maxlength="200" placeholder="Paste a project website, name or token address"><button type="submit" class="primary-button">Check token ${icon('arrow')}</button></form><div class="scan-bottom"><div class="examples"><span>Start with</span><button data-action="investigate" data-address="${SOL}">SOL</button><button data-action="investigate" data-address="${CURATED[2]}">BONK</button><button data-action="investigate" data-address="${CURATED[1]}">JUP</button></div><span class="scan-note">${icon('lock')} ${backendConfig?.accessMode==='holders-only'?'Holder verification for bundle scans':backendConfig?.accessMode==='free-basic'?'Basic scans need no wallet':'Wallet optional for token research'}</span></div></div>`;}
function home(){
 const draft=$('#scan-input')?.value||'';const inputFocused=document.activeElement===$('#scan-input');const sol=market.find(p=>p.baseToken.address===SOL);
 $('#main').innerHTML=`<section class="hero" aria-labelledby="hero-heading"><span class="hero-label"><span class="network-dot"></span> BUNDLE INTELLIGENCE. BUILT ON PROOF.</span><h1 id="hero-heading">See the wallets.<br><span>Follow the supply.</span><svg class="conviction-arrow" viewBox="0 0 100 100" aria-hidden="true"><path d="m15 78 63-63M25 15h53v53" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="square"/></svg></h1><p>Check the token. Inspect the acquisition patterns.<br>Follow the source evidence, wallet by wallet.</p>${scanForm()}<div class="hero-proof"><span>${icon('circlecheck')} Automatic free scans</span><span>${icon('shield')} Transaction proof</span><span>${icon('files')} Wallet patterns</span></div></section>
 ${technologyPreview()}<div class="market-pulse"><span class="pulse-label"><span class="network-dot"></span> SOLANA MAINNET</span><span class="pulse-price">SOL <strong>${sol?money(sol.priceUsd):'—'}</strong>${sol?`<span class="${Number(sol.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(sol.priceChange?.h24))}</span>`:''}</span><span class="pulse-note">${sol?'24h change · largest indexed SOL pool':'Loading a live quote'}</span><a href="#/checks">${storage.checks.length} saved scan${storage.checks.length===1?'':'s'} ${icon('arrow')}</a></div>
 <section class="market-section" aria-labelledby="radar-title"><div class="section-header"><div><span class="eyebrow">YOUR NEXT DEEP DIVE</span><h2 id="radar-title">Find your signal.</h2></div><div class="section-controls"><button class="text-button" data-action="refresh-market" ${marketLoading?'disabled':''}>${icon('refresh')}Refresh</button><div class="view-options" role="group" aria-label="Market display"><button class="icon-button ${view==='grid'?'selected':''}" data-action="view" data-view="grid" aria-label="Card view" aria-pressed="${view==='grid'}">${icon('grid')}</button><button class="icon-button ${view==='list'?'selected':''}" data-action="view" data-view="list" aria-label="Table view" aria-pressed="${view==='list'}">${icon('list')}</button></div></div></div><div id="market-content">${marketContent()}</div><div class="market-footer"><span>Prices & pools via <a href="https://dexscreener.com" target="_blank" rel="noopener noreferrer">DEX Screener ${icon('external')}</a></span><span>${marketTime?'Updated '+marketTime.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',hour12:false}):marketError?'Source unavailable':'Fetching live data…'}</span></div></section>
 <section class="how-strip" aria-label="Three steps to better research"><div><span>01</span><strong>Find a token.</strong><p>Paste a mint, name, or project link.</p></div><div><span>02</span><strong>Read the signals.</strong><p>Transaction patterns. Source evidence.</p></div><div><span>03</span><strong>Keep your proof.</strong><p>Save, watch, and revisit.</p></div><a href="#/methodology" aria-label="Read the methodology">${icon('arrow')}</a></section>
 <div class="closing-note">Every launch has a trail.<br><span>Follow the PROOF.</span><button class="text-button" data-action="focus-search">Check your first token ${icon('arrow')}</button></div>`;
 if($('#scan-input')){$('#scan-input').value=draft;if(inputFocused)$('#scan-input').focus();}
 if(!marketLoading&&!marketTime&&!marketError)loadMarket();
}
function tokenIcon(token,pair,size=''){const url=safeUrl(pair?.info?.imageUrl);return url?`<img class="token-icon ${size}" src="${esc(url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="token-icon ${size}" aria-hidden="true">${esc((token.symbol||'?').slice(0,2))}</span>`;}
function tokenCell(p){return `<div class="token-cell">${tokenIcon(p.baseToken,p)}<div><span class="token-name">${esc(p.baseToken.symbol)} <small>SOL</small></span><span class="token-address">${esc(short(p.baseToken.address,5))}</span></div></div>`;}
function watched(address){return storage.watch.some(t=>t.address===address);}
function watchButton(p){const yes=watched(p.baseToken.address);return `<button class="icon-button ${yes?'bookmarked':''}" data-action="watch" data-address="${esc(p.baseToken.address)}" aria-label="${yes?'Remove '+esc(p.baseToken.symbol)+' from':'Add '+esc(p.baseToken.symbol)+' to'} watchlist" aria-pressed="${yes}">${icon('bookmark')}</button>`;}
function marketRows(pairs){if(view==='grid')return `<div class="card-grid">${pairs.map(p=>`<article class="market-card"><div class="card-top">${tokenCell(p)}${watchButton(p)}</div><div class="card-data"><div><small>PRICE</small><strong class="mono">${money(p.priceUsd)}</strong></div><div><small>24H CHANGE</small><strong class="mono ${Number(p.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(p.priceChange?.h24))}</strong></div><div><small>LIQUIDITY</small><strong class="mono">${money(p.liquidity?.usd,true)}</strong></div></div><button class="inspect-button" data-action="investigate" data-address="${esc(p.baseToken.address)}">Scan token ${icon('arrow')}</button></article>`).join('')}</div>`;
 return `<div class="scroll-table"><table class="market-table"><thead><tr><th>PROJECT</th><th>PRICE</th><th>24H CHANGE</th><th class="hide-small">LIQUIDITY</th><th class="hide-medium">SAVED REPORT</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${pairs.map(p=>`<tr><td>${tokenCell(p)}</td><td class="mono">${money(p.priceUsd)}</td><td class="mono ${Number(p.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(p.priceChange?.h24))}</td><td class="mono hide-small">${money(p.liquidity?.usd,true)}</td><td class="hide-medium"><span class="research-state">${icon(reports.has(p.baseToken.address)?'circlecheck':'clock')}${reports.has(p.baseToken.address)?'Report saved':'Not scanned'}</span></td><td><div class="table-actions">${watchButton(p)}<button class="inspect-button" data-action="investigate" data-address="${esc(p.baseToken.address)}">Scan ${icon('arrow')}</button></div></td></tr>`).join('')}</tbody></table></div>`;}
function empty(title,message,name='files',action='Scan a token',target='/'){return `<div class="empty-state">${icon(name)}<h2>${esc(title)}</h2><p>${esc(message)}</p>${action?`<a class="primary-button" href="#${target}">${esc(action)} ${icon('arrow')}</a>`:''}</div>`;}
function loadingRows(){return `<div aria-label="Loading live market data" role="status">${Array.from({length:4},()=>'<div class="loading-row"><span class="skeleton"></span><span class="skeleton"></span><span class="skeleton"></span></div>').join('')}</div>`;}
function marketContent(){if(marketError)return `<div class="error-box"><strong>Market data is temporarily unavailable</strong>${esc(marketError)}<br><button class="secondary-button" data-action="refresh-market">Try again ${icon('refresh')}</button></div>`;if(!market.length)return loadingRows();const pairs=activeMarket==='all'?market:market.filter(p=>watched(p.baseToken.address));return pairs.length?marketRows(pairs):empty('Keep your signals close','Bookmark a project to add it to your personal watchlist.','bookmark','','/');}
async function loadMarket(force=false){if(marketLoading)return;marketLoading=true;marketError='';try{const pairs=await fetchJSON('https://api.dexscreener.com/tokens/v1/solana/'+CURATED.join(','));if(!Array.isArray(pairs))throw new Error('The market source returned an unexpected response.');market=CURATED.map(a=>primaryPair(pairs,a)).filter(Boolean);if(!market.length)throw new Error('The market source returned no matching token pools.');marketTime=new Date();}catch(e){marketError=e.message;if(force)toast(e.message);}finally{marketLoading=false;if(route()==='/')home();}}
function investigationList(){const q=$('#history-filter')?.value||'';const checks=storage.checks.filter(r=>(r.token.name+' '+r.token.symbol+' '+r.address).toLowerCase().includes(q.toLowerCase()));return checks.map(r=>`<article class="history-item">${tokenIcon(r.token,r.pair)}<div><h3>${esc(r.token.name)} <span class="token-address">${esc(r.token.symbol)} · ${esc(short(r.address,6))}</span></h3><p>${new Date(r.at).toLocaleDateString('en-US',{month:'short',day:'numeric'})} · ${esc(scoreEvidence(r).band)} · ${scoreEvidence(r).total}/100 · ${scoreEvidence(r).coverage}% coverage</p></div><a class="inspect-button" href="#/report/${esc(r.address)}">Open report ${icon('external')}</a><button class="icon-button" data-action="delete-report" data-address="${esc(r.address)}" aria-label="Delete ${esc(r.token.symbol)} report">${icon('trash')}</button></article>`).join('')||'<p class="search-label">No investigations match this filter.</p>';}
function checks(){const action=`<a class="primary-button" href="#/">New scan ${icon('arrow')}</a>`;$('#main').innerHTML=intro('Saved scans','Your research. Ready when you are.',action)+bundleHistoryMarkup()+(storage.checks.length?`<div class="toolbar-filter"><label class="sr-only" for="history-filter">Filter investigations</label><input id="history-filter" type="search" placeholder="Filter by name, ticker or address…"></div><div class="report-history" id="history-list">${investigationList()}</div>`:empty('Your proof starts here','Scan a Solana token. Your report will be saved here to revisit or export.'));}
async function watchlist(){const epoch=renderEpoch;$('#main').innerHTML=intro('Your watchlist','Keep an eye on the projects that matter to you.',`<a class="primary-button" href="#/">Discover projects ${icon('arrow')}</a>`)+(storage.watch.length?`<div id="watch-content">${loadingRows()}</div>`:empty('Keep your signals close','Use the bookmark beside a project to save it here. Your watchlist stays in this browser.','bookmark','Explore projects'));if(!storage.watch.length)return;try{const addresses=storage.watch.map(t=>t.address);const batches=[];for(let i=0;i<addresses.length;i+=30)batches.push(addresses.slice(i,i+30));const data=(await Promise.all(batches.map(b=>fetchJSON('https://api.dexscreener.com/tokens/v1/solana/'+b.join(','))))).flat();if(renderEpoch!==epoch)return;const pairs=addresses.map(a=>primaryPair(data,a)).filter(Boolean);$('#watch-content').innerHTML=pairs.length?marketRows(pairs):empty('No current market data','The market source did not return matching pools. Your bookmarks are still saved.','info','Explore projects');const absent=storage.watch.filter(t=>!pairs.some(p=>p.baseToken.address===t.address));if(absent.length)$('#watch-content').insertAdjacentHTML('beforeend',absent.map(t=>`<div class="history-item"><div><strong>${esc(t.symbol||short(t.address))}</strong><p>Market data unavailable · ${esc(short(t.address,6))}</p></div><button class="secondary-button" data-action="watch" data-address="${esc(t.address)}">Remove</button></div>`).join(''));}catch(e){if(renderEpoch===epoch)$('#watch-content').innerHTML=`<div class="error-box"><strong>Unable to refresh your watchlist</strong>${esc(e.message)}<br><button class="secondary-button" data-action="retry-watchlist">Try again</button></div>`;}}
function account(){const connected=wallet&&walletProvider;$('#main').innerHTML=intro('Your account','Your wallet, your workspace, your rules.')+`<div class="account-grid"><div><section class="panel"><div class="panel-header"><h2>Wallet</h2>${connected?'<span class="connection-status"><span class="network-dot"></span> Connected</span>':'<span class="local-badge">READ-ONLY</span>'}</div><div class="panel-body">${connected?`<h3>Connected to Solana</h3><div class="address-box"><code>${esc(wallet)}</code><button class="icon-button" data-action="copy" data-value="${esc(wallet)}" aria-label="Copy wallet address">${icon('copy')}</button></div><div class="balance">${balance===null?'—':balance.toLocaleString('en-US',{maximumFractionDigits:5})} <span class="positive">SOL</span></div><p>${balance===null?'Balance unavailable. You can retry the public mainnet RPC.':'Mainnet balance · fetched from Solana RPC'}</p><div class="button-row"><a href="https://solscan.io/account/${esc(wallet)}" class="secondary-button" target="_blank" rel="noopener noreferrer">View on Solscan ${icon('external')}</a><button class="secondary-button" data-action="refresh-balance">${icon('refresh')} Refresh</button><button class="danger-button" data-action="disconnect-wallet">Disconnect</button></div>`:`<div class="wallet-illustration">${icon('wallet')}</div><h3>Your wallet. Always in your control.</h3><p>Connect Phantom or Solflare to view your Solana mainnet address and balance. Your research works with or without a wallet.</p><button class="primary-button" data-action="connect-wallet">${icon('wallet')} Connect wallet ${icon('arrow')}</button>`}<p class="wallet-note">${icon('lock')} Connection is read-only. Pro verification signs a login message; never a transaction or token approval.</p></div></section><section class="panel"><div class="panel-header"><h2>Your research library</h2><span class="local-badge">THIS BROWSER</span></div><div class="panel-body"><div class="settings-stat"><div><strong>${String(storage.checks.length).padStart(2,'0')}</strong><small>Investigations</small></div><div><strong>${String(storage.watch.length).padStart(2,'0')}</strong><small>Watchlist projects</small></div></div><p>Reports and watchlists are stored on this device. Wallet connection does not sync them. Export a copy to keep your evidence.</p><div class="button-row"><button class="secondary-button" data-action="export-library">${icon('download')} Export research</button><button class="danger-button" data-action="clear-library">Clear local data</button></div></div></section></div><div><section class="panel"><div class="panel-header"><h2>Workspace settings</h2>${icon('sun')}</div><div class="panel-body"><div class="settings-row"><div><strong>Appearance</strong><p>Make the desk your own.</p></div><label class="sr-only" for="theme-setting">Color theme</label><select id="theme-setting" class="select"><option value="dark" ${storage.theme==='dark'?'selected':''}>Dark</option><option value="light" ${storage.theme==='light'?'selected':''}>Light</option></select></div><div class="settings-row"><div><strong>Table density</strong><p>A little more room, or a little less.</p></div><label class="sr-only" for="density-setting">Table density</label><select id="density-setting" class="select"><option value="comfortable" ${storage.density!=='compact'?'selected':''}>Comfortable</option><option value="compact" ${storage.density==='compact'?'selected':''}>Compact</option></select></div><div class="settings-row"><div><strong>Network</strong><p>All research uses real mainnet data.</p></div><span class="connection-status"><span class="network-dot"></span>Solana</span></div></div></section><section class="panel"><div class="panel-header"><h2>Built on evidence</h2>${icon('shield')}</div><div class="panel-body"><p>Proof Bundles checks observable token permissions and indexed markets. It does not certify projects, hold funds, or promise returns.</p><a href="#/methodology" class="text-button">Understand every signal ${icon('external')}</a></div></section><div class="bottom-banner">${icon('info')}<div><strong>Proof Bundles · Holder utility</strong><p>Project ticker: PROOF. Official token contract is not configured.</p></div></div></div></div>`;}
function methodology(){$('#main').innerHTML=intro('Evidence over hype.','An open methodology. Every point explained.')+`<div class="prose"><section class="panel"><div class="panel-header"><h2>What a bundle check can establish</h2></div><div class="panel-body"><p>The basic RPC scan examines up to 12 successful transactions from the latest 60 mint-address signatures. An optional signature reads up to 12 matching transactions from that slot. The slot is labeled a mint-initialization slot only when the signed transaction contains a parsed initialization for this exact mint. Neither mode proves complete launch coverage. Two distinct signer-owned recipient accounts acquiring this mint in at least two transactions in one slot form a same-slot pattern. Acquisitions can be transfers, not buys. This does not prove a Jito bundle or common wallet ownership.</p><p>The Pro native engine verifies an initialization transaction for this exact mint and reads up to five slots from that point. Automatic discovery checks at most 2,000 mint signatures and four candidate transactions; it is not a full historical index. Creation must be verified or no launch report is produced. Up to six recipient balances and three funding lookbacks are queried, with exact coverage shown. Positive acquisitions, window net changes and current holdings are separate values. Shared funding sources do not prove identity or coordination.</p><p>Pro access requires a signed, expiring login challenge and a fresh server-side mainnet balance check. Connecting alone does not grant Pro. Free Proof score reports remain available independently of indexed launch evidence.</p></div></section><section class="panel"><div class="panel-body"><span class="eyebrow">THE PROOF APPROACH</span><h3>Know what’s checked. Know what isn’t.</h3><p>Proof Bundles is an independent Solana research workspace inspired by the idea that every claim deserves evidence. Its reports are deterministic data checks, not an AI audit or a financial recommendation.</p></div></section><div class="method-step"><span>01 /</span><div><h2>Start with the exact address.</h2><p>Paste a Solana mint address, a Solscan token link, or search for a project. Names and tickers can be copied. Always confirm the contract address through an independent official source. DEX Screener pair links are resolved to their base token. Project website searches match indexed website links to candidate Solana tokens; they do not verify website functionality or ownership.</p></div></div><div class="method-step"><span>02 /</span><div><h2>Read the permissions.</h2><p>We request the parsed mint account from <a href="https://solana.com/docs/rpc/http/getaccountinfo" target="_blank" rel="noopener noreferrer">Solana mainnet RPC ↗</a>. An active mint authority can increase supply; an active freeze authority can freeze eligible accounts. Revoked authorities reduce those specific powers, but do not establish safety. Token-2022 extensions need additional review.</p></div></div><div class="method-step"><span>03 /</span><div><h2>Follow the market evidence.</h2><p><a href="https://docs.dexscreener.com/api/reference" target="_blank" rel="noopener noreferrer">DEX Screener ↗</a> provides prices, volume, liquidity, trading activity and pool age. We select the largest indexed base-token pool by reported USD liquidity. Figures describe that pool, not the whole token market. Liquidity below $100,000 and pool age under seven days are flagged for review. These thresholds are research heuristics.</p></div></div><section class="panel scoring-methodology" id="score-rules"><div class="panel-header"><h2>How the Proof score works</h2><span class="local-badge">V1.0 · OUT OF 100</span></div><div class="panel-body"><p>The Proof score is a transparent checklist of observable signals. It does not predict returns or establish whether a project is legitimate. Unknown inputs score zero; we never divide by only the available categories.</p><div class="score-rules-list"><p><strong>Mint permission · 20:</strong> revoked = 20; active = 0.</p><p><strong>Freeze permission · 15:</strong> revoked = 15; active = 0.</p><p><strong>Pool liquidity · 25:</strong> ≥$1m = 25; ≥$100k = 20; ≥$25k = 10; ≥$10k = 5; below = 0.</p><p><strong>Pool history · 15:</strong> ≥180 days = 15; ≥30 = 12; ≥7 = 8; ≥1 = 3; below = 0.</p><p><strong>Trading presence · 10:</strong> 24h pool transactions ≥1,000 = 10; ≥100 = 7; ≥10 = 4; >0 = 1; zero = 0.</p><p><strong>Top-account spread · 10:</strong> top 10 token accounts ≤20% of supply = 10; ≤40% = 6; ≤60% = 3; above = 0. This includes pool and treasury accounts, not unique holders.</p><p><strong>Indexed links · 5:</strong> website = 3; social = 2. These are index listings; we do not test site functionality or ownership.</p></div><p>Coverage shows the weight of categories with usable data. Below 70% coverage, the result is labeled “Incomplete evidence.” At sufficient coverage: ≥80 points = “More supporting signals”; ≥50 = “Mixed signals”; below = “Limited supporting signals.” All scores are based on the displayed snapshot time.</p></div></section><div class="method-step"><span>04 /</span><div><h2>Leave room for the unknown.</h2><p>We do not verify teams, business claims, product functionality, contract source code, liquidity locks, unique holder identities, wash trading or rug-pull risk. A report with no flagged signals is not a clean bill of health. Unavailable data is labeled unknown. Missing API fields are never treated as positive evidence.</p></div></div><div class="method-step"><span>05 /</span><div><h2>Keep the receipts.</h2><p>Every report includes a score breakdown, source links and timestamp. Share links rerun a scan for the recipient; an exported JSON file preserves the original snapshot. Reports and watchlists are stored in your browser and can be exported. Saved reports are snapshots; use Refresh evidence to fetch new data. Public APIs can be rate limited or unavailable, and indexed data can lag the chain.</p></div></div><div class="bottom-banner">${icon('lock')}<div><strong>Connection is read-only.</strong><p>Proof Bundles requests wallet access and balance data. Connecting is read-only. Pro ownership verification separately signs a login message; it never approves a token or sends a transaction.</p></div></div></div>`;}
async function submitQuery(query){
 const parsed=parseInput(query);
 if(parsed.type==='address'){startInvestigation(parsed.value);return;}
 if(['pair','website','search'].includes(parsed.type)){
  if(parsed.type==='search'&&/^[1-9A-HJ-NP-Za-km-z]{30,50}$/.test(parsed.value)){toast('That address does not decode to a 32-byte Solana public key. Check the full mint address.');return;}
  navigate('/search?q='+encodeURIComponent(parsed.type==='website'?parsed.value:parsed.type==='pair'?query:parsed.value));return;
 }
 toast('Enter a project name, ticker, public website, or Solana mainnet mint address. Social links and other networks are not scanned.');
}
function searchResultsMarkup(results,q,parsed){
 const explanation=parsed.type==='website'?`Matched the indexed website ${esc(parsed.host)}. This does not verify site ownership or product claims.`:'Names and tickers can be copied. Confirm the mint address before scanning.';
 return results.length?`<p class="search-label"><strong>${results.length} Solana match${results.length===1?'':'es'}</strong> for “${esc(q)}”</p><div class="search-proof-note">${icon('info')}<span>${explanation} Choose a token to generate its score and evidence report.</span></div>${marketRows(results)}`:empty('No indexed project match','Try the exact Solana mint address or a project name. Website lookup uses indexed links; unlisted projects and sites without a token may not appear.','search','Back to research');
}
async function searchPage(){
 const epoch=renderEpoch;
 const q=new URLSearchParams(route().split('?')[1]).get('q')||'';
 const parsed=parseInput(q);
 $('#main').innerHTML=intro('Find the project. Then follow the proof.','Choose the exact token to get a mainnet evidence score.')+`<form id="project-search" class="inline-search"><label class="sr-only" for="project-query">Project website, name or ticker</label><input id="project-query" name="query" value="${esc(q)}" placeholder="Project website, name or ticker…" required maxlength="200"><button class="primary-button" type="submit">Find project ${icon('search')}</button></form><div id="search-content">${loadingRows()}</div>`;
 try{
  let pairs;
  if(parsed.type==='pair'){
   const data=await fetchJSON('https://api.dexscreener.com/latest/dex/pairs/solana/'+parsed.value);pairs=data.pairs||[];
  }else if(['website','search'].includes(parsed.type)){
   if(parsed.type==='website'){
    const answers=await Promise.allSettled(websiteQueries(parsed).map(query=>fetchJSON('https://api.dexscreener.com/latest/dex/search?q='+encodeURIComponent(query))));
    if(answers.every(a=>a.status==='rejected'))throw answers[0].reason;
    pairs=answers.flatMap(a=>a.status==='fulfilled'&&Array.isArray(a.value.pairs)?a.value.pairs:[]).filter(p=>(p.info?.websites||[]).some(w=>siteMatches(w.url,parsed.value)));
   }else{
    const data=await fetchJSON('https://api.dexscreener.com/latest/dex/search?q='+encodeURIComponent(parsed.value));pairs=data.pairs||[];
   }
  }else throw new Error('Use a project name, website or supported Solana token link.');
  if(renderEpoch!==epoch)return;
  const byAddress=new Map();
  pairs.filter(p=>p.chainId==='solana'&&validAddress(p.baseToken?.address||'')).sort((a,b)=>(Number(b.liquidity?.usd)||0)-(Number(a.liquidity?.usd)||0)).forEach(p=>{if(!byAddress.has(p.baseToken.address))byAddress.set(p.baseToken.address,p);});
  const results=[...byAddress.values()].slice(0,20);window.searchPairs=results;
  $('#search-content').innerHTML=searchResultsMarkup(results,q,parsed);
 }catch(e){if(renderEpoch===epoch)$('#search-content').innerHTML=`<div class="error-box"><strong>Project search is temporarily unavailable</strong>${esc(e.message)}<button class="secondary-button" data-action="retry-search">Try again</button></div>`;}
}
function reportLoading(address){$('#main').innerHTML=`<a class="text-button" href="#/">← Back to research</a><div class="loading-investigation" role="status"><div class="scan-animation">${icon('radar')}</div><span class="eyebrow">FOLLOWING THE EVIDENCE</span><h1>Let’s see what’s on-chain.</h1><p class="mono">${esc(short(address,10))}</p><div class="progress-steps"><div class="active">${icon('check')} Solana mainnet address validated</div><div>${icon('activity')} Fetching indexed market evidence</div><div>${icon('shield')} Reading mint and freeze permissions</div><div>${icon('files')} Checking account spread and scoring the evidence</div></div><p>Public APIs can take up to 20 seconds. Missing sources are marked unknown. No wallet connection required.</p></div>`;}
async function startInvestigation(address,force=false){if(!validAddress(address)){toast('Please provide a valid Solana mint address.');return;}if(force)reports.delete(address);if(route()!=='/report/'+address)navigate('/report/'+address);else render();}
function isReportRoute(address){return route()==='/report/'+address||route().startsWith('/report/'+address+'/snapshot/');}
async function reportPage(address){if(!validAddress(address)){$('#main').innerHTML=empty('Invalid token address','This report link does not contain a valid Solana public key.','warning');return;}const existing=reports.get(address);if(existing){renderReport(existing);return;}reportLoading(address);if(reportPending.has(address))return;reportPending.add(address);try{const [dexResult,chainResult,largestResult]=await Promise.allSettled([fetchJSON('https://api.dexscreener.com/latest/dex/tokens/'+address),rpc('getAccountInfo',[address,{encoding:'jsonParsed',commitment:'confirmed'}]),rpc('getTokenLargestAccounts',[address,{commitment:'confirmed'}])]);const dex=dexResult.status==='fulfilled'?dexResult.value:null;const chain=chainResult.status==='fulfilled'?chainResult.value:null;const pair=primaryPair(dex?.pairs,address);if(!pair&&chain?.value?.data?.parsed?.type!=='mint'){if(chainResult.status==='fulfilled')throw new Error(chain?.value?'This address is not a supported parsed SPL token mint. Try the token’s mint address instead of a wallet or pool address.':'This account was not found on Solana mainnet. Confirm the exact token mint address.');throw new Error('Neither a matching indexed market nor a parsed on-chain mint could be retrieved. The public sources may be unavailable. Please retry.');}
 const token=pair?.baseToken||{address,symbol:'SPL',name:'Unindexed SPL token'};const report={schema:2,address,token,pair,chain,largestAccounts:largestResult.status==='fulfilled'?largestResult.value:null,sources:{market:dexResult.status==='fulfilled',mint:chainResult.status==='fulfilled',largestAccounts:largestResult.status==='fulfilled'},at:new Date().toISOString(),assessment:assess(pair,chain,address,dexResult.status==='fulfilled')};report.score=scoreEvidence(report);reports.set(address,report);persist('checks',[report,...storage.checks.filter(r=>r.address!==address)].slice(0,100));if(isReportRoute(address))renderReport(report);
 }catch(e){if(isReportRoute(address))$('#main').innerHTML=intro('Evidence unavailable','The sources did not return enough data for this scan.')+`<div class="error-box"><strong>This check needs another look</strong>${esc(e.message)}<div class="button-row"><button class="secondary-button" data-action="retry-report" data-address="${esc(address)}">${icon('refresh')} Retry check</button><a class="secondary-button" href="#/">Back to research</a></div></div>`;}finally{reportPending.delete(address);}}
function scoreCard(score){
 return `<section class="proof-score-panel" aria-labelledby="proof-score-title"><div class="proof-score-overview"><span class="eyebrow" id="proof-score-title">PROOF SCORE / MAINNET EVIDENCE</span><div class="proof-score-number"><strong id="proof-score-value">${score.coverage?score.total:'—'}</strong><span>/100</span></div><h2>${esc(score.band)}</h2><p>Points from observable data checks. This is not a safety, legitimacy, or investment rating.</p><div class="coverage-row"><strong>${score.coverage}%</strong> evidence coverage · ${score.known}/${score.count} scored inputs available</div><progress max="100" value="${score.coverage}" aria-label="Evidence coverage ${score.coverage}%"></progress><p class="score-fine">Missing evidence earns zero points. Click a category to see the calculation and source.</p><a class="text-button" href="#/methodology">Full scoring rules ${icon('arrow')}</a></div><div class="proof-score-categories">${score.categories.map(c=>`<details class="score-category ${c.state}"><summary><span class="score-category-label">${icon(c.state==='unknown'?'info':c.state==='observed'?'circlecheck':'warning')}${esc(c.label)}</span><span class="score-points">${c.points===null?'Unknown':c.points+' / '+c.max} <span class="score-chevron">+</span></span></summary><div class="score-category-detail"><p>${esc(c.detail)}</p><a href="${esc(safeUrl(c.url))}" target="_blank" rel="noopener noreferrer">Check the source ${icon('external')}</a></div></details>`).join('')}<div class="score-version">MODEL V${esc(score.version)} · THE SAME RULES FOR EVERY PROJECT</div></div></section>`;
}
function concentrationProof(concentration){
 return `<details class="panel holder-proof"><summary>View top token-account evidence <span>${concentration.percent.toFixed(2)}% combined · ${concentration.accounts.length} accounts</span></summary><div class="panel-body"><p>These are token accounts, not identified people. Pools, vaults and treasuries can dominate the list.</p>${concentration.accounts.map(a=>`<a class="report-source" href="https://solscan.io/account/${esc(a.address)}" target="_blank" rel="noopener noreferrer"><code>${esc(short(a.address,7))}</code><span>${esc(a.amount)} raw units ${icon('external')}</span></a>`).join('')}<p>Largest-accounts RPC slot: ${esc(concentration.slot??'unavailable')}. Raw values are preserved in the JSON export.</p></div></details>`;
}
function renderReport(r){const p=r.pair,a=r.assessment;const score=scoreEvidence(r);r.score=score;const yes=watched(r.address);$('#main').innerHTML=`<a class="text-button" href="#/checks">← Saved scans</a><div class="report-top"><div class="report-token">${tokenIcon(r.token,p,'large')}<div><h1>${esc(r.token.name)}</h1><span class="token-address">${esc(r.token.symbol)} · SOLANA MAINNET · ${esc(short(r.address,6))} <button class="text-button" data-action="copy" data-value="${esc(r.address)}" aria-label="Copy token address">Copy address ${icon('copy')}</button></span></div></div><div class="button-row"><button class="secondary-button" data-action="copy" data-value="${esc(location.origin+location.pathname+'#/report/'+r.address)}">${icon('copy')}Share</button><button class="secondary-button ${yes?'bookmarked':''}" data-action="watch" data-address="${esc(r.address)}">${icon('bookmark')}${yes?'Watching':'Watch project'}</button><button class="secondary-button" data-action="export-report" data-address="${esc(r.address)}">${icon('download')}Export</button><button class="primary-button" data-action="retry-report" data-address="${esc(r.address)}">${icon('refresh')}Refresh evidence</button></div></div><div class="report-date">EVIDENCE SNAPSHOT · ${new Date(r.at).toLocaleString('en-US',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})} UTC · SAVED IN THIS BROWSER</div><section class="panel bundle-panel" id="bundle-report-panel" data-mint="${esc(r.address)}"><div class="panel-body">Loading bundle tools…</div></section>${scoreCard(score)}${score.concentration?concentrationProof(score.concentration):''}<section class="report-summary ${a.flags?'caution':''}">${icon(a.flags?'warning':'shield')}<div><span class="eyebrow">${a.flags} FLAGGED · ${a.missing} NEED${a.missing===1?'S':''} MANUAL REVIEW · DETERMINISTIC CHECK</span><h2>${esc(a.title)}</h2><p>${esc(a.summary)}</p></div></section><div class="report-grid"><section class="panel"><div class="panel-header"><h2>The evidence</h2><span class="local-badge">SOURCE-LINKED</span></div>${a.checks.map(c=>`<div class="evidence-item">${icon(c.status==='pass'?'circlecheck':c.status==='caution'?'warning':'info',c.status==='pass'?'positive':c.status==='caution'?'negative':'')}<div><strong>${esc(c.name)} <span class="local-badge">${c.status==='pass'?'OBSERVED':c.status==='caution'?'REVIEW':c.status==='info'?'CONTEXT':'UNKNOWN'}</span></strong><p>${esc(c.detail)}</p><small>${esc(c.source)}</small></div></div>`).join('')}</section><div><section class="panel"><div class="panel-header"><h2>Market snapshot</h2><span class="local-badge">LARGEST INDEXED POOL</span></div><div class="panel-body"><div class="report-metrics"><div><small>Price</small><strong>${money(p?.priceUsd)}</strong></div><div><small>24h change</small><strong class="${Number(p?.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(p?.priceChange?.h24))}</strong></div><div><small>Pool liquidity</small><strong>${money(p?.liquidity?.usd,true)}</strong></div><div><small>24h pool volume</small><strong>${money(p?.volume?.h24,true)}</strong></div><div><small>Market cap</small><strong>${money(p?.marketCap,true)}</strong></div><div><small>Pool / venue</small><strong>${esc(p?.dexId||'—')}</strong></div></div><p class="report-note">These figures describe the selected pool. They can change quickly and may lag the chain.</p></div></section><section class="panel"><div class="panel-header"><h2>Check the sources</h2>${icon('external')}</div><div class="panel-body"><a class="report-source" href="https://solscan.io/token/${esc(r.address)}" target="_blank" rel="noopener noreferrer">Solscan <span>Mint account ↗</span></a>${safeUrl(p?.url)?`<a class="report-source" href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">DEX Screener <span>Pool & market evidence ↗</span></a>`:''}<a class="report-source" href="https://explorer.solana.com/address/${esc(r.address)}" target="_blank" rel="noopener noreferrer">Solana Explorer <span>Mainnet account ↗</span></a>${(p?.info?.websites||[]).filter(w=>safeUrl(w.url)).slice(0,2).map(w=>`<a class="report-source" href="${esc(safeUrl(w.url))}" target="_blank" rel="noopener noreferrer">Project website <span>Unverified external claim ↗</span></a>`).join('')}</div></section><div class="bottom-banner">${icon('info')}<div><strong>A signal is a starting point.</strong><p>No flags does not mean no risk. Read the <a href="#/methodology">methodology ↗</a>.</p></div></div></div></div>`;loadBundlePanel(r.address);}
function render(){if(activeBundleRequest){activeBundleRequest.controller.abort();activeBundleRequest=null;}renderEpoch++;updateNavigation();const r=route();if(r==='/')home();else if(r==='/me')account();else if(r==='/checks')checks();else if(r==='/watchlist')watchlist();else if(r==='/methodology')methodology();else if(r==='/technology')technologyPage();else if(r==='/pro')proPage();else if(r.startsWith('/report/'))reportPage(r.split('/')[2]);else if(r.startsWith('/search?'))searchPage();else{$('#main').innerHTML=empty('This page is off the radar','Head back to your research desk to continue.','search');}window.scrollTo(0,0);}
function openModal(title,body){modalTrigger=document.activeElement;$('#modal').innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${body}`;$('#modal-overlay').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#modal button, #modal input, #modal a')?.focus(),0);}
function closeModal(){if(closeListener){closeListener();closeListener=null;}$('#modal-overlay').hidden=true;document.body.style.overflow='';modalTrigger?.focus();}
function walletModal(){if(wallet){navigate('/me');return;}openModal('Connect your wallet',`<p>View your Solana mainnet address and balance. Your wallet stays in your control.</p><button class="wallet-option" data-action="choose-wallet" data-provider="phantom"><span>◕</span>Phantom <small>${window.phantom?.solana?.isPhantom||window.solana?.isPhantom?'Detected':'Open wallet site ↗'}</small></button><button class="wallet-option solflare" data-action="choose-wallet" data-provider="solflare"><span>☀</span>Solflare <small>${window.solflare?.isSolflare?'Detected':'Open wallet site ↗'}</small></button><p class="modal-fine">Connection requests access to your public address. Connecting does not sign anything. Pro holder verification separately requests a login message; never a transaction or token approval.</p>`);}
async function connectWallet(name){const provider=name==='phantom'?(window.phantom?.solana||(window.solana?.isPhantom?window.solana:null)):(window.solflare?.isSolflare?window.solflare:null);if(!provider){window.open(name==='phantom'?'https://phantom.com':'https://solflare.com','_blank','noopener,noreferrer');toast('Install or open the wallet, then return to connect. On mobile, use its in-app browser.');return;}try{const result=await provider.connect();const address=(result?.publicKey||provider.publicKey)?.toString();if(!validAddress(address||''))throw new Error('The wallet did not return a valid Solana address.');wallet=address;walletProvider=provider;balance=null;updateWalletLabel();provider.on?.('accountChanged',walletChanged);provider.on?.('disconnect',walletDisconnected);closeModal();toast('Wallet connected. Read-only access.');navigate('/me');await refreshBalance();}catch(e){toast(e.code===4001?'Wallet connection cancelled.':e.message||'Unable to connect this wallet.');}}
function walletChanged(key){holderState={wallet:null,pro:false};apiCall('/api/auth/logout',{}).catch(()=>{});if(!key){walletDisconnected();return;}const address=key.toString();if(!validAddress(address)){walletDisconnected();return;}wallet=address;balance=null;updateWalletLabel();if(route()==='/me')account();refreshBalance();}
function walletDisconnected(){walletProvider?.removeListener?.('accountChanged',walletChanged);walletProvider?.removeListener?.('disconnect',walletDisconnected);holderState={wallet:null,pro:false};apiCall('/api/auth/logout',{}).catch(()=>{});wallet=null;walletProvider=null;balance=null;updateWalletLabel();if(route()==='/me')account();}
async function refreshBalance(){if(!wallet)return;const address=wallet;try{const r=await rpc('getBalance',[address,{commitment:'confirmed'}]);if(wallet!==address)return;balance=Number(r.value)/1e9;if(route()==='/me')account();}catch{toast('The public mainnet RPC could not fetch this balance. Try again shortly.');}}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function toggleWatch(address){if(watched(address)){persist('watch',storage.watch.filter(t=>t.address!==address));toast('Project removed from your watchlist.');}else{if(storage.watch.length>=90){toast('Your watchlist holds up to 90 projects. Remove one before adding another.');return;}const p=[...market,...(window.searchPairs||[])].find(p=>p.baseToken.address===address);const report=reports.get(address);const token=p?.baseToken||report?.token||{symbol:short(address),name:short(address)};persist('watch',[...storage.watch,{address,symbol:token.symbol,name:token.name}]);toast('Project added to your watchlist.');}const r=route();if(r==='/')home();else if(r.startsWith('/report/')){const report=reports.get(address);if(report)renderReport(report);}else if(r==='/watchlist')watchlist();else if(r.startsWith('/search')){const q=new URLSearchParams(r.split('?')[1]).get('q')||'';const results=window.searchPairs||[];$('#search-content').innerHTML=searchResultsMarkup(results,q,parseInput(q));}}
const actions={
 'bundle-tab':el=>{bundleViewState.tab=el.dataset.tab;repaintBundleResult();},
 'filter-bundle-owner':el=>{bundleViewState.owner=el.dataset.owner;bundleViewState.query='';bundleViewState.tab='wallets';repaintBundleResult();},
 'clear-bundle-owner':()=>{bundleViewState.owner='';bundleViewState.query='';repaintBundleResult();},
 'compare-bundle':()=>{bundleViewState.compare=!bundleViewState.compare;repaintBundleResult();},
 'stop-bundle-wait':()=>activeBundleRequest?.controller.abort(),
 'open-bundle-snapshot':el=>{const r=storage.bundleSnapshots.find(r=>snapshotId(r)===el.dataset.snapshot);if(!r)return;bundleEvidence.set(r.mint,r);bundleViewState={tab:'overview',owner:'',query:'',compare:false};navigate('/report/'+r.mint+'/snapshot/'+encodeURIComponent(snapshotId(r)));},
 'delete-bundle-snapshot':el=>{const removed=storage.bundleSnapshots.find(r=>snapshotId(r)===el.dataset.snapshot);persist('bundleSnapshots',storage.bundleSnapshots.filter(r=>snapshotId(r)!==el.dataset.snapshot));if(removed&&bundleEvidence.get(removed.mint)?.scannedAt===removed.scannedAt){bundleEvidence.delete(removed.mint);const next=storage.bundleSnapshots.find(r=>r.mint===removed.mint);if(next)bundleEvidence.set(next.mint,next);}checks();},
 'bundle-scan':el=>runBundleScan(el.dataset.mint),
 'retry-bundle':()=>{const mint=$('#bundle-report-panel')?.dataset.mint;if(mint)runBundleScan(mint);},
 'bundle-indexed':el=>runIndexedScan(el.dataset.mint),
 'verify-holder':()=>verifyHolder(),
 'refresh-holder':()=>refreshHolder(),
'investigate':el=>startInvestigation(el.dataset.address),
'focus-search':()=>quickSearch(),
 'token-info':()=>navigate('/pro'),
 'old-token-info':()=>openModal('Proof Bundles · Holder utility',`<div class="token-brand-badge">$PROOF</div><p>PROOF is the project ticker for Proof Bundles.</p><p>An official Solana token contract has not been configured. No token price, supply, or purchase link is published here.</p><p class="modal-fine">Token research is live on mainnet and works without holding a token.</p><a class="secondary-button" href="#/methodology" data-action="token-methodology">How the app works ${icon('arrow')}</a>`),
 'token-methodology':()=>{closeModal();navigate('/methodology');},
'view':el=>{view=el.dataset.view;if(route()==='/')home();else if(route()==='/watchlist')watchlist();else if(route().startsWith('/search'))searchPage();},
'market-tab':el=>{activeMarket=el.dataset.tab;home();},
'refresh-market':()=>{loadMarket(true);home();},
'watch':el=>toggleWatch(el.dataset.address),
'retry-watchlist':()=>watchlist(),
'retry-search':()=>searchPage(),
'retry-report':el=>startInvestigation(el.dataset.address,true),
'copy':async el=>{try{await navigator.clipboard.writeText(el.dataset.value);toast('Copied to clipboard.');}catch{toast('Clipboard is unavailable in this browser. You can select and copy the address.');}},
'connect-wallet':()=>walletModal(),
'choose-wallet':el=>connectWallet(el.dataset.provider),
'disconnect-wallet':async()=>{const p=walletProvider;walletDisconnected();try{await p?.disconnect();}catch{}toast('Wallet disconnected.');},
'refresh-balance':()=>refreshBalance(),
'close-modal':()=>closeModal(),
'export-library':()=>{download('proof-bundles-research-'+new Date().toISOString().slice(0,10)+'.json',{app:'Proof Bundles',ticker:'PROOF',schema:1,exportedAt:new Date().toISOString(),network:'solana-mainnet',checks:storage.checks.map(r=>({...r,score:scoreEvidence(r)})),watchlist:storage.watch,bundleSnapshots:storage.bundleSnapshots});toast('Research library exported.');},
'export-report':el=>{const r=reports.get(el.dataset.address);if(r){r.score=scoreEvidence(r);download('proof-bundles-'+r.token.symbol.replace(/[^a-z0-9]/gi,'').slice(0,15)+'-'+r.address.slice(0,6)+'.json',r);}},
'clear-library':()=>openModal('Clear this research library?',`<p>This removes all ${storage.checks.length} saved investigations and ${storage.watch.length} bookmarks and ${storage.bundleSnapshots.length} bundle snapshots from this browser. Export a copy first if you want to keep them.</p><div class="button-row"><button class="secondary-button" data-action="close-modal">Keep my research</button><button class="primary-button" data-action="confirm-clear">Clear local data</button></div>`),
'confirm-clear':()=>{persist('checks',[]);persist('watch',[]);persist('bundleSnapshots',[]);bundleEvidence.clear();reports.clear();closeModal();account();toast('Local research library cleared.');},
'delete-report':el=>{const address=el.dataset.address;persist('checks',storage.checks.filter(r=>r.address!==address));reports.delete(address);checks();toast('Saved report deleted.');}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const action=actions[el.dataset.action];if(action){e.preventDefault();Promise.resolve(action(el)).catch(()=>toast('That action could not complete. Please try again.'));}}});
document.addEventListener('submit',e=>{if(e.target.id==='scan-form'||e.target.id==='project-search'){e.preventDefault();submitQuery(new FormData(e.target).get('query'));}});
document.addEventListener('change',e=>{if(e.target.id==='theme-setting'){persist('theme',e.target.value);applySettings();}if(e.target.id==='density-setting'){persist('density',e.target.value);applySettings();}});
document.addEventListener('input',e=>{if(e.target.id==='history-filter')$('#history-list').innerHTML=investigationList();});
$('#theme-toggle').addEventListener('click',()=>{persist('theme',storage.theme==='dark'?'light':'dark');applySettings();});


function quickSearch(){if(route()==='/'){$('#scan-input')?.focus();$('#scan-input')?.scrollIntoView({block:'center',behavior:'smooth'});}else{navigate('/');setTimeout(()=>$('#scan-input')?.focus(),50);}}

$('#modal-overlay').addEventListener('click',e=>{if(e.target===$('#modal-overlay'))closeModal();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();quickSearch();}if(e.key==='Escape'){if(!$('#modal-overlay').hidden)closeModal();}if(e.key==='Tab'&&!$('#modal-overlay').hidden){const items=$$('#modal button:not([disabled]),#modal a,#modal input,#modal select');const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('input',e=>{
 if(e.target.id==='launch-anchor'){const mint=$('#bundle-report-panel')?.dataset.mint;if(mint)bundleAnchorDrafts.set(mint,e.target.value);}
 if(e.target.id==='bundle-wallet-filter'){bundleViewState.query=e.target.value;const r=bundleEvidence.get($('#bundle-report-panel')?.dataset.mint);if(r)$('#bundle-wallet-rows').innerHTML=bundleWalletTable(bundleWalletRows(r).filter(w=>(!bundleViewState.owner||w.owner===bundleViewState.owner)&&w.owner.toLowerCase().includes(bundleViewState.query.toLowerCase())),r);}
 if(e.target.id==='bundle-history-query'){const q=e.target.value.toLowerCase();$('#bundle-history-items').innerHTML=bundleHistoryRows(storage.bundleSnapshots.filter(r=>[r.mint,reports.get(r.mint)?.token?.name,reports.get(r.mint)?.token?.symbol].join(' ').toLowerCase().includes(q)));}
});
window.addEventListener('hashchange',render);
if(location.pathname==='/me'&&!location.hash)location.hash='/me';
async function apiCall(path,body,signal){
 const res=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:signal?AbortSignal.any([signal,AbortSignal.timeout(path.includes('/launch')?180000:90000)]):AbortSignal.timeout(path.includes('/launch')?180000:90000)});
 const data=await res.json().catch(()=>({}));if(!res.ok){const e=new Error(data.error?.message||'The bundle service could not complete this request.');e.code=data.error?.code;e.status=res.status;e.retryAfter=Number(res.headers.get('Retry-After')||data.error?.retryAfter)||0;throw e;}return data;
}
async function getBackendConfig(){if(!backendConfig)backendConfig=await apiCall('/api/config');return backendConfig;}
const bundlePct=value=>typeof value==='number'&&Number.isFinite(value)?value.toFixed(2)+'%':'Unknown';
function bundleError(error){return `<div class="error-box"><strong>${['CREATION_NOT_LOCATED','CREATION_ANCHOR_REQUIRED'].includes(error.code)?'Creation proof required':error.code==='LAUNCH_NOT_INDEXED'?'Launch not indexed':error.code==='PRO_REQUIRED'?'Holder threshold not met':'Evidence unavailable'}</strong>${esc(error.message)}${error.retryAfter?'<p>Retry after '+error.retryAfter+' seconds.</p>':''}<p>No bundle verdict was produced.</p>${error.code==='RATE_LIMIT'?'<button class="secondary-button" data-action="retry-bundle">Retry scan</button>':''}${['WALLET_LOGIN_REQUIRED','PRO_REQUIRED','HOLDER_CONFIG_REQUIRED'].includes(error.code)?'<a class="secondary-button" href="#/pro">View holder access</a>':''}</div>`;}
async function loadBundlePanel(mint){
 if(bundleViewMint!==mint){bundleViewState={tab:'overview',owner:'',query:'',compare:false};bundleViewMint=mint;}
 let panel=$('#bundle-report-panel');if(!panel||panel.dataset.mint!==mint)return;
 try{const cfg=await getBackendConfig();if(!$('#bundle-report-panel')||$('#bundle-report-panel').dataset.mint!==mint)return;
  panel=$('#bundle-report-panel');if(!panel||panel.dataset.mint!==mint)return;let savedId='';try{savedId=decodeURIComponent(route().split('/snapshot/')[1]||'');}catch{}const stored=savedId?storage.bundleSnapshots.find(r=>r.mint===mint&&snapshotId(r)===savedId):bundleEvidence.get(mint);if(stored)bundleEvidence.set(mint,stored);
  panel.innerHTML=`<div class="panel-header"><h2>Bundle evidence</h2><a class="text-button" href="#/pro">Holder Pro ${icon('arrow')}</a></div><div class="panel-body"><p class="bundle-intro">Inspect recent signer-owned acquisitions for same-slot patterns. Our Pro engine verifies mint creation and reads a bounded launch window directly from Solana RPC.</p><div class="bundle-scan-controls"><label for="launch-anchor">Optional transaction signature <small>Reads the anchor slot; verifies mint initialization only when present.</small></label><input id="launch-anchor" value="${esc(bundleAnchorDrafts.get(mint)||'')}" placeholder="Paste a signature, or leave blank for recent activity" maxlength="90" spellcheck="false"><div class="button-row"><button class="primary-button" data-action="bundle-scan" data-mint="${esc(mint)}" ${cfg.accessMode==='pending'?'disabled':''}>${icon('radar')}Run free bundle scan</button><button class="secondary-button" data-action="bundle-indexed" data-mint="${esc(mint)}" ${!cfg.nativeLaunchAvailable||cfg.accessMode==='pending'?'disabled':''}>${icon('lock')}Deep launch scan · Pro</button></div><p class="bundle-status-note">${cfg.accessMode==='pending'?'Scan access policy is awaiting owner setup.':cfg.accessMode==='holders-only'?'Holder verification is required for bundle scans.':'Basic sampled scans are free.'} Native Pro analysis uses Solana RPC. A creation signature improves coverage for older or active tokens. See <a href="#/technology">how bundle detection works</a>.</p></div>${stored?'<p class="saved-bundle-note">Saved snapshot · '+new Date(stored.scannedAt).toLocaleString()+'. Refresh to check current activity.</p>':''}<div id="bundle-result">${stored?renderBundleResult(stored):savedId?'<div class="bundle-empty">This snapshot is not stored in this browser. Run a new scan to inspect current evidence.</div>':'<div class="bundle-empty">Run a basic sample, or verify holder access for our own launch-window analysis.</div>'}</div></div>`;
  if(!stored&&!savedId&&cfg.accessMode==='free-basic')await runBundleScan(mint);
 }catch(e){panel.innerHTML=`<div class="panel-header"><h2>Bundle evidence</h2></div><div class="panel-body">${bundleError(e)}</div>`;}
}
function renderIndexedBundleResult(r){
 if(r.mode==='indexed-launch')return `<div class="bundle-result-head"><span class="eyebrow">PRO · INDEXED LAUNCH EVIDENCE</span><h3>${r.providerReportedBundle===true?'Indexer reports a bundle':r.providerReportedBundle===false?'Indexer reports no same-slot bundle':'Indexer verdict unknown'}</h3><p>Source: <a href="${esc(safeUrl(r.sourceUrl))}" target="_blank" rel="noopener noreferrer">GateKept ${icon('external')}</a> · Launch slot ${esc(r.slot??'unknown')} · Updated ${esc(r.updatedAt||'unknown')}</p></div><div class="bundle-metrics"><div><small>INITIAL GROUP ALLOCATION</small><strong>${bundlePct(r.initialSupplyPct)}</strong></div><div><small>BUNDLE WALLETS AT LAUNCH</small><strong>${bundlePct(r.bundleWalletsPct)}</strong></div><div><small>REPORTED HELD NOW</small><strong>${bundlePct(r.currentlyHeldPct)}</strong></div></div><div class="button-row"><a class="secondary-button" href="/api/bundles/export?id=${esc(r.reportId)}&format=json">${icon('download')}JSON evidence</a><a class="secondary-button" href="/api/bundles/export?id=${esc(r.reportId)}&format=csv">${icon('download')}Wallet CSV</a></div><div class="bundle-wallets">${r.wallets.map(w=>`<a class="report-source" href="https://solscan.io/account/${esc(w.address)}" target="_blank" rel="noopener noreferrer"><code>${esc(short(w.address,8))}</code><span>${bundlePct(w.pct)} at launch ${icon('external')}</span></a>`).join('')||'<p>No bundle wallet list was supplied.</p>'}</div><p class="bundle-status-note">${esc(r.cluster.length)} related indexed launches; ${esc(r.knownWallets.length)} previously seen wallet records. These are provider records, not independent wallet-identity proof.</p><div class="bundle-limits">${r.limitations.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`;
}
function bundleHistoryMarkup(){
 const items=storage.bundleSnapshots;
 return `<section class="panel bundle-history-panel"><div class="panel-header"><h2>Bundle snapshots</h2><span class="local-badge">${items.length} SAVED · THIS BROWSER</span></div><div class="panel-body">${items.length?`<label class="sr-only" for="bundle-history-query">Filter bundle snapshots</label><input class="bundle-search" id="bundle-history-query" type="search" placeholder="Filter snapshots by token or mint…"><div id="bundle-history-items">${bundleHistoryRows(items)}</div>`:'<p>Run a bundle scan to keep a timestamped snapshot here. Reopening a snapshot does not automatically scan again.</p>'}</div></section>`;
}
function bundleHistoryRows(items){return `<div class="bundle-history-scroll">${items.map(r=>{const s=bundleSummary(r);const token=reports.get(r.mint)?.token;return `<article class="bundle-history-row"><div><strong>${esc(token?.symbol||short(r.mint,6))}</strong><span>${new Date(r.scannedAt).toLocaleString()} · ${s.groups} pattern${s.groups===1?'':'s'} · ${s.coverage}% transaction coverage</span></div><button class="inspect-button" data-action="open-bundle-snapshot" data-snapshot="${esc(snapshotId(r))}">Open ${icon('arrow')}</button><button class="icon-button" data-action="delete-bundle-snapshot" data-snapshot="${esc(snapshotId(r))}" aria-label="Delete this bundle snapshot">${icon('trash')}</button></article>`;}).join('')||'<p>No snapshots match this filter.</p>'}</div>`;}
function rememberBundle(r){
 if(r.mode!=='sampled-rpc'||!validBundleSnapshot(r))return;
 persist('bundleSnapshots',keepBundleSnapshot(storage.bundleSnapshots,r));
}
function priorBundle(r){return storage.bundleSnapshots.find(p=>p.mint===r.mint&&Date.parse(p.scannedAt)<Date.parse(r.scannedAt));}
function nativeUnits(value,decimals){if(typeof value!=='string')return 'Unknown';const negative=value.startsWith('-');const exact=formatTokenUnits(negative?value.slice(1):value,decimals);return exact===null?value+' raw units':(negative?'-':'')+exact;}
function renderNativeLaunchResult(r){
 const c=r.coverage,init=r.initialization,groups=r.evidence.groups;const nativeRows=bundleViewState.owner?r.recipients.filter(w=>w.address===bundleViewState.owner):r.recipients;
 return `<div class="bundle-verdict ${c.completeWindow?'observed':'partial'}"><div class="bundle-verdict-top"><span>${icon('radar')} OUR ENGINE · DIRECT SOLANA RPC</span><span>${new Date(r.scannedAt).toLocaleTimeString()}${r.cached?' · cached':''}</span></div><h3>Creation verified. ${groups.length} acquisition pattern${groups.length===1?'':'s'} observed.</h3><p>${c.completeWindow?'The produced blocks in this bounded window were read. This is not a Jito-bundle or ownership verdict.':'Some launch-window evidence is missing, truncated, or still forming. Treat this as a partial report.'}</p><div class="native-source"><a href="https://solscan.io/tx/${esc(init.signature)}" target="_blank" rel="noopener noreferrer">Mint-creation proof · slot ${init.slot} ${icon('external')}</a><span>Window ${c.startSlot}–${c.endSlot} · ${c.readSlots.length}/${c.requestedSlots.length} requested blocks read</span></div></div>
 <div class="bundle-metrics"><div><small>MINT TRANSACTIONS ANALYZED</small><strong>${c.analyzedTransactions}</strong></div><div><small>SIGNER RECIPIENTS OBSERVED</small><strong>${r.recipients.length}</strong></div><div><small>CURRENT BALANCES CHECKED</small><strong>${c.balancesRead}<span> / ${c.recipientCount}</span></strong></div></div>
 <div class="button-row"><a class="secondary-button" href="/api/bundles/export?id=${esc(r.reportId)}&format=json">${icon('download')}Launch evidence JSON</a><a class="secondary-button" href="/api/bundles/export?id=${esc(r.reportId)}&format=csv">${icon('download')}Recipient CSV</a></div>
 ${techniqueMarkup(r.evidence)}<section class="native-section"><div class="bundle-map-heading"><div><h4>Observed launch-window associations</h4><p>Slot membership, not proof of a bundle or common owner.</p></div>${bundleViewState.owner?'<button class="text-button" data-action="clear-bundle-owner">Show all recipients</button>':''}</div>${walletMap(r.evidence,bundleViewState.owner)}</section><section class="native-section"><h4>Recipient positions in the read window</h4><p>Observed positive acquisitions can include transfers or allocations. Net change is limited to the analyzed window. Current balances are separate, later RPC reads.</p>${nativeRows.length?`<div class="bundle-wallet-table"><table><thead><tr><th>RECIPIENT OWNER</th><th>POSITIVE ACQUISITIONS</th><th>WINDOW NET CHANGE</th><th>CURRENT BALANCE</th><th>CURRENT SUPPLY</th></tr></thead><tbody>${nativeRows.map(w=>`<tr><td><a href="https://solscan.io/account/${esc(w.address)}" target="_blank" rel="noopener noreferrer"><code>${esc(short(w.address,6))}</code>${icon('external')}</a><details><summary>${w.proofs.length} acquisition proof${w.proofs.length===1?'':'s'}</summary>${w.proofs.map(p=>`<a href="https://solscan.io/tx/${esc(p.signature)}" target="_blank" rel="noopener noreferrer">slot ${p.slot} · ${esc(short(p.signature,5))}</a>`).join('')}</details></td><td><code>${esc(nativeUnits(w.positiveAcquisitionsRaw,r.token.decimals))}</code></td><td><code>${esc(nativeUnits(w.windowNetChangeRaw,r.token.decimals))}</code></td><td><code>${esc(nativeUnits(w.currentBalanceRaw,r.token.decimals))}</code><small>${w.currentSlot?'RPC slot '+w.currentSlot:'Not checked or unavailable'}</small></td><td>${bundlePct(w.currentSupplyPct)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="bundle-empty">No signer-owned positive acquisitions could be attributed in the read window.</div>'}</section>
 <section class="native-section"><h4>Pre-acquisition funding lookback</h4><p>${r.fundingCoverage.walletsRead}/${r.fundingCoverage.walletsRequested} selected wallets read · ${r.fundingCoverage.transactionsRead} prior transactions parsed · ${r.fundingCoverage.failedTransactions} unavailable. This is a small lookback, not a complete root-funder trace.</p>${r.fundingSources.length?r.fundingSources.map(f=>`<details class="bundle-group"><summary>${esc(short(f.source,8))} <span>${f.recipients.length} recipient${f.recipients.length===1?'':'s'} · ${f.shared?'shared observed source':'direct observed source'}</span></summary><div>${f.transfers.map(t=>`<a class="report-source" href="https://solscan.io/tx/${esc(t.signature)}" target="_blank" rel="noopener noreferrer">${esc(short(t.recipient,6))}<span>${(t.lamports/1e9).toFixed(5)} SOL · slot ${esc(t.slot)} ${icon('external')}</span></a>`).join('')}</div></details>`).join(''):'<div class="bundle-empty">No inbound SOL transfer was established in the selected lookback. Funding origins remain unverified.</div>'}</section>
 <details class="bundle-scope-details"><summary>Exact coverage and limitations</summary><p>Creation ${c.historySearch.explicitAnchor?'was supplied and verified':'was found in a bounded history search'}. ${c.historySearch.signaturesExamined} mint signatures examined; ${c.historySearch.transactionsProbed} candidate transactions probed. This does not claim a full-history index.</p><p>Requested slots: ${esc(c.requestedSlots.join(', '))}. Unavailable slots: ${esc(c.failedSlots.join(', ')||'none')}. Slot enumeration: ${c.slotEnumerationKnown?'known':'unknown'}. Window fully elapsed: ${c.windowMatured?'yes':'not established'}. Mint transaction truncation: ${c.transactionsTruncated?'yes':'no'}. Read budget reached: ${c.readBudgetReached?'yes':'no'}. Transactions without usable metadata in read blocks: ${c.unavailableMetadata}.</p>${init.feePayer?`<p>Initialization fee payer: <a href="https://solscan.io/account/${esc(init.feePayer)}" target="_blank" rel="noopener noreferrer">${esc(init.feePayer)}</a>. This is not a verified developer identity.</p>`:''}${r.limitations.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`;
}

function renderBundleResult(r){
 if(r.mode==='native-launch')return renderNativeLaunchResult(r);
 if(r.mode==='indexed-launch')return renderIndexedBundleResult(r);
 const summary=bundleSummary(r);const state=bundleViewState;const previous=priorBundle(r);const c=r.coverage;
 const rows=bundleWalletRows(r).filter(row=>(!state.owner||state.owner===row.owner)&&(!state.query||row.owner.toLowerCase().includes(state.query.toLowerCase())));
 return `<div class="bundle-verdict ${summary.tone}"><div class="bundle-verdict-top"><span>${icon(summary.incomplete?'info':summary.groups?'activity':'shield')} ${summary.incomplete?'PARTIAL TRANSACTION COVERAGE':'BOUNDED TRANSACTION SAMPLE'}</span><span>${new Date(r.scannedAt).toLocaleTimeString()}${r.cached?' · cached':''}</span></div><h3>${esc(summary.headline)}</h3><p>${esc(summary.explanation)}</p><div class="bundle-coverage"><progress max="100" value="${summary.coverage}" aria-label="${summary.coverage}% of requested transactions analyzed"></progress><span><strong>${summary.analyzed}/${summary.requested}</strong> requested transactions analyzed · ${summary.coverage}%</span></div></div>
 <div class="bundle-metrics"><div><small>SAME-SLOT PATTERNS</small><strong>${summary.groups}</strong></div><div><small>GROUPED RECIPIENTS</small><strong>${summary.wallets}</strong></div><div><small>FAILED / UNAVAILABLE</small><strong>${esc(c.failed)}</strong></div></div>
 <div class="bundle-context"><span>${summary.launchVerified?'Mint initialization observed in anchor slot':'Full launch coverage not verified'}</span><span>${esc(c.scope)}</span></div>
 ${techniqueMarkup(r)}<div class="bundle-toolbar"><div class="bundle-tabs" role="group" aria-label="Bundle evidence view">${[['overview','Wallet map'],['wallets','Wallet evidence'],['timeline','Pattern slots']].map(([key,label])=>`<button class="${state.tab===key?'active':''}" data-action="bundle-tab" data-tab="${key}" aria-pressed="${state.tab===key}">${label}</button>`).join('')}</div>${previous?`<button class="text-button" data-action="compare-bundle">${icon('files')}${state.compare?'Hide comparison':'Compare snapshot'}</button>`:''}</div>
 ${state.compare&&previous?bundleComparisonMarkup(r,previous):''}
 <section id="bundle-evidence-view">${state.tab==='overview'?`<div class="bundle-map-heading"><div><h4>Who appears together?</h4><p>Signer-owned recipients grouped by their observed slot.</p></div>${state.owner?'<button class="text-button" data-action="clear-bundle-owner">Clear selection</button>':''}</div>${walletMap(r,state.owner)}<div class="bundle-map-footer"><span>${summary.wallets} unique grouped recipient${summary.wallets===1?'':'s'} in this sample</span><button class="text-button" data-action="bundle-tab" data-tab="wallets">Inspect transaction proof ${icon('arrow')}</button></div>`:state.tab==='wallets'?`<div class="bundle-wallet-toolbar"><label class="sr-only" for="bundle-wallet-filter">Filter recipient wallets</label><input id="bundle-wallet-filter" class="bundle-search" type="search" value="${esc(state.query)}" placeholder="Find a recipient wallet…">${state.owner?`<button class="secondary-button" data-action="clear-bundle-owner">${esc(short(state.owner))} ${icon('x')}</button>`:''}</div><div id="bundle-wallet-rows">${bundleWalletTable(rows,r)}</div>`:bundleTimeline(r)}</section>
 <details class="bundle-scope-details"><summary>What was checked, and what was not</summary><p>Window: ${c.firstTime?new Date(c.firstTime*1000).toLocaleString():'Unknown'} → ${c.lastTime?new Date(c.lastTime*1000).toLocaleString():'Unknown'}. ${esc(c.acquisitionTransactions)} analyzed transactions had positive signer-owned mint balance changes. ${esc(c.unattributedBalances)} balance entries lacked usable owner or amount data.</p>${r.limitations.map(t=>`<p>${esc(t)}</p>`).join('')}</details>${bundleTransfers(r)}`;
}
function bundleWalletTable(rows,r){
 if(!rows.length)return '<div class="bundle-empty">No recipient wallets match this filter. A limited sample without a pattern does not establish an unbundled launch.</div>';
 return `<div class="bundle-wallet-table"><table><thead><tr><th>RECIPIENT OWNER</th><th>ACQUISITIONS</th><th>OBSERVED POSITIVE GAINS</th><th>PROOF</th></tr></thead><tbody>${rows.map(row=>`<tr><td><a href="https://solscan.io/account/${esc(row.owner)}" target="_blank" rel="noopener noreferrer"><code>${esc(short(row.owner,7))}</code>${icon('external')}</a></td><td>${row.transactionCount} tx · ${row.slots.length} slot${row.slots.length===1?'':'s'}</td><td><code>${esc(formatTokenUnits(row.rawAcquired,r.token?.decimals)??row.rawAcquired)}</code><small>${formatTokenUnits(row.rawAcquired,r.token?.decimals)===null?'raw token units':'token units'} · not current holdings</small></td><td><details><summary>${row.proofs.length} transaction${row.proofs.length===1?'':'s'}</summary>${row.proofs.map(p=>`<a href="https://solscan.io/tx/${esc(p.signature)}" target="_blank" rel="noopener noreferrer">${esc(short(p.signature,5))} · slot ${p.slot}${icon('external')}</a>`).join('')}</details></td></tr>`).join('')}</tbody></table></div>`;
}
function bundleTimeline(r){
 if(!r.groups.length)return '<div class="bundle-empty">No multi-wallet same-slot groups were observed in this sample.</div>';
 return `<div class="bundle-timeline">${[...r.groups].sort((a,b)=>a.slot-b.slot).map(g=>`<article><div class="timeline-marker"></div><div><span class="eyebrow">${g.blockTime?new Date(g.blockTime*1000).toLocaleString():'Time unavailable'}</span><h4>Slot ${g.slot}</h4><p>${g.owners.length} recipient owners · ${g.transactions.length} acquisition transactions</p><div class="timeline-wallets">${g.owners.map(owner=>`<button data-action="filter-bundle-owner" data-owner="${esc(owner)}">${esc(short(owner,5))}</button>`).join('')}</div>${g.transactions.map(t=>`<a class="text-button" href="https://solscan.io/tx/${esc(t.signature)}" target="_blank" rel="noopener noreferrer">${esc(short(t.signature,8))} ${icon('external')}</a>`).join('')}</div></article>`).join('')}</div>`;
}
function bundleComparisonMarkup(current,previous){
 const diff=compareBundleSnapshots(current,previous);if(!diff)return '';
 return `<section class="bundle-comparison"><span class="eyebrow">SNAPSHOT COMPARISON · ${diff.sameAnchor?'SAME ANCHOR':'DIFFERENT WINDOWS'}</span><h4>Compared with ${new Date(previous.scannedAt).toLocaleString()}</h4><p>${esc(diff.description)}</p><div><span><strong>${diff.groupDelta>0?'+':''}${diff.groupDelta}</strong> observed groups</span><span><strong>${diff.added.length}</strong> newly observed recipients</span><span><strong>${diff.removed.length}</strong> recipients not in this sample</span></div></section>`;
}
function bundleTransfers(r){
 if(!r.sharedTransfers.length)return '';
 return `<details class="bundle-scope-details"><summary>Shared SOL transfers in the sample · ${r.sharedTransfers.length} source${r.sharedTransfers.length===1?'':'s'}</summary><p>These transfers were observed within sampled transactions. They do not establish root funding or common ownership.</p>${r.sharedTransfers.map(f=>`<div class="bundle-group"><a class="report-source" href="https://solscan.io/account/${esc(f.source)}" target="_blank" rel="noopener noreferrer">${esc(short(f.source,8))}<span>${f.destinations.length} recipients ${icon('external')}</span></a>${f.transfers.map(t=>`<a class="report-source" href="https://solscan.io/tx/${esc(t.signature)}" target="_blank" rel="noopener noreferrer">${esc(short(t.destination,8))}<span>${(t.lamports/1e9).toFixed(5)} SOL ${icon('external')}</span></a>`).join('')}</div>`).join('')}</details>`;
}
function repaintBundleResult(){const mint=$('#bundle-report-panel')?.dataset.mint;const report=bundleEvidence.get(mint);if(report&&$('#bundle-result'))$('#bundle-result').innerHTML=renderBundleResult(report);}

async function runBundleScan(mint){
 const target=$('#bundle-result');if(!target)return;
 if(activeBundleRequest)activeBundleRequest.controller.abort();
 const request={mint,controller:new AbortController()};activeBundleRequest=request;
 const anchor=$('#launch-anchor')?.value.trim()||'';
 target.innerHTML=`<div class="bundle-scan-progress" role="status"><div class="scan-animation">${icon('radar')}</div><h3>Following the evidence.</h3><p>Fetching the mint, transaction sample, and signer-owned balance changes.</p><div><span>MAINNET</span><span>${anchor?'ANCHOR SLOT':'RECENT ACTIVITY'}</span><span>UP TO 12 TRANSACTIONS</span></div><button class="secondary-button" data-action="stop-bundle-wait">Stop waiting</button><small>Upstream requests may finish and be cached after you leave.</small></div>`;
 const buttons=$$('.bundle-scan-controls button');buttons.forEach(b=>b.disabled=true);
 try{
  const result=await apiCall('/api/bundles/scan',{mint,anchor},request.controller.signal);
  if(!validBundleSnapshot(result))throw new Error('The scanner returned an invalid evidence response. No snapshot was saved.');bundleEvidence.set(mint,result);rememberBundle(result);bundleViewState={tab:'overview',owner:'',query:'',compare:false};
  if(activeBundleRequest===request&&$('#bundle-report-panel')?.dataset.mint===mint){history.replaceState(null,'','#/report/'+mint);$('#bundle-result').innerHTML=renderBundleResult(result);}
 }catch(e){
  if(activeBundleRequest===request&&$('#bundle-report-panel')?.dataset.mint===mint)$('#bundle-result').innerHTML=e.name==='AbortError'?'<div class="bundle-empty">Stopped waiting. No new result has been added to your library. You can return to the last saved snapshot or run another scan.</div>':bundleError(e);
 }finally{if(activeBundleRequest===request)activeBundleRequest=null;buttons.forEach(b=>b.disabled=b.dataset.action==='bundle-indexed'?!backendConfig?.nativeLaunchAvailable:backendConfig?.accessMode==='pending');}
}
async function runIndexedScan(mint){
 const anchor=$('#launch-anchor')?.value.trim()||bundleAnchorDrafts.get(mint)||'';bundleAnchorDrafts.set(mint,anchor);
 if(!holderState.pro){try{holderState=await apiCall('/api/session');}catch{}if(!holderState.pro){navigate('/pro');return;}}const target=$('#bundle-result');if(!target)return;
 const buttons=$$('.bundle-scan-controls button');buttons.forEach(b=>b.disabled=true);
 target.innerHTML='<div class="bundle-empty" role="status">Our engine is verifying creation, reading launch-window blocks, and checking selected recipient balances and funding history. Historical RPC reads may take up to two minutes.</div>';
 try{const result=await apiCall('/api/bundles/launch',{mint,anchor});bundleEvidence.set(mint,result);if($('#bundle-report-panel')?.dataset.mint===mint)$('#bundle-result').innerHTML=renderBundleResult(result);}catch(e){if(e.status===401)holderState={wallet:null,pro:false};if($('#bundle-report-panel')?.dataset.mint===mint)$('#bundle-result').innerHTML=bundleError(e);}finally{buttons.forEach(b=>b.disabled=b.dataset.action==='bundle-indexed'?!backendConfig?.nativeLaunchAvailable:backendConfig?.accessMode==='pending');}
}
async function refreshHolder(){try{holderState=await apiCall('/api/session');if(route()==='/pro')proPage(false);}catch(e){toast(e.message);}}
async function verifyHolder(){
 const cfg=await getBackendConfig();if(!cfg.holder.configured){toast('The owner must configure the official holder mint and minimum token amount first.');return;}
 if(!wallet||!walletProvider){walletModal();return;}if(typeof walletProvider.signMessage!=='function'){toast('This wallet cannot sign the required login message. Use Phantom or Solflare.');return;}
 try{const challenge=await apiCall('/api/auth/challenge',{wallet});const signed=await walletProvider.signMessage(new TextEncoder().encode(challenge.message),'utf8');const signature=signed.signature||signed;await apiCall('/api/auth/verify',{id:challenge.id,wallet,signature:btoa(String.fromCharCode(...signature))});holderState=await apiCall('/api/session');toast(holderState.pro?'Holder access verified.':holderState.message||'Wallet verified; holder threshold not met.');proPage(false);}catch(e){toast(e.code===4001?'Verification cancelled.':e.message);}
}
function holderSteps(cfg){
 const identified=!!wallet||!!holderState.wallet;const signed=!!holderState.wallet;const balance=holderState.pro?'complete':holderState.code==='PRO_REQUIRED'?'blocked':'';
 return `<div class="pro-access-steps" role="list" aria-label="Holder verification steps">${[[identified?'complete':'','Wallet identified',identified?'Ready':'Connect'],[signed?'complete':'','Ownership verified',signed?'Signed session':'Sign message'],[balance,'Holding checked',holderState.pro?'Qualified':holderState.code==='PRO_REQUIRED'?'Below threshold':cfg.holder.configured?'Waiting':'Policy not set']].map(([state,label,status])=>`<div class="pro-access-step ${state}" role="listitem">${icon(state==='complete'?'circlecheck':state==='blocked'?'warning':'clock')}<span>${label}</span><span>${status}</span></div>`).join('')}</div>`;
}
async function proPage(refresh=true){
 $('#main').innerHTML=intro('Pro for holders.','Deeper launch evidence. Verified access. No trading permissions.')+'<div class="bundle-empty" role="status">Loading holder policy…</div>';
 try{const cfg=await getBackendConfig();if(refresh)holderState=await apiCall('/api/session');if(route()!=='/pro')return;
 $('#main').innerHTML=intro('Pro for holders.','Deeper launch evidence. Verified access. No trading permissions.')+`<div class="account-grid"><section class="panel"><div class="panel-header"><h2>Holder access</h2><span class="local-badge">${holderState.pro?'VERIFIED':cfg.holder.configured?'VERIFICATION REQUIRED':'NOT CONFIGURED'}</span></div><div class="panel-body"><span class="eyebrow">PROOF BUNDLES PRO</span><h3>${holderState.pro?'Your holder access is verified.':cfg.holder.configured?'Hold. Verify. Investigate.':cfg.holder.policyConfigured?'Holder verification awaiting setup.':'Holder policy awaiting setup.'}</h3><p>${cfg.holder.configured?'Required balance: '+esc(cfg.holder.minimumTokens)+' tokens of the exact mint below.':cfg.holder.policyConfigured&&cfg.holder.sharedStateReady===false?'The holder policy is set, but verification is awaiting access-service setup. Free scans remain available.':'The official mint and minimum holding have not been configured. No wallet is granted Pro until both are set and verified.'}</p>${cfg.holder.configured?`<div class="address-box"><code>${esc(cfg.holder.mint)}</code><a href="https://solscan.io/token/${esc(cfg.holder.mint)}" target="_blank" rel="noopener noreferrer">${icon('external')}</a></div>`:''}${holderSteps(cfg)}<div class="button-row pro-buttons"><button class="primary-button" data-action="verify-holder" ${!cfg.holder.configured?'disabled':''}>${icon('wallet')}${wallet?'Verify holder access':'Connect & verify'}</button><button class="secondary-button" data-action="refresh-holder">${icon('refresh')}Recheck session</button></div><p class="wallet-note">${icon('lock')}Verification signs a login message only. No transaction, token approval or transfer.</p>${holderState.wallet?`<p>Verified wallet: ${esc(short(holderState.wallet,8))}. ${esc(holderState.pro?'Balance checked at '+holderState.verified.verifiedAt:holderState.message||'Holder access is not active.')}</p>`:''}<p class="bundle-status-note">Sessions expire after 10 minutes. Protected scans and exports recheck your mainnet balance server-side.</p></div></section><div><section class="panel"><div class="panel-header"><h2>Pro research utility</h2></div><div class="panel-body"><div class="pro-feature">${icon('radar')}<div><strong>Our own launch-window engine</strong><p>Verified mint creation, read-window acquisition groups, and source-linked transactions directly from Solana RPC.</p></div></div><div class="pro-feature">${icon('files')}<div><strong>Recipient and funding evidence</strong><p>Selected current token balances and a bounded pre-acquisition SOL funding lookback. Missing reads remain explicit.</p></div></div><div class="pro-feature">${icon('download')}<div><strong>Evidence exports</strong><p>CSV wallet lists and JSON launch reports, protected by holder verification.</p></div></div><p class="bundle-status-note">Gatekept is not required. A dedicated archival SOLANA_RPC_URL improves historical coverage; automatic creation lookup is bounded and may require the exact creation signature.</p></div></section><div class="bottom-banner">${icon('info')}<div><strong>Evidence is the utility.</strong><p>Holding a token unlocks configured research access. It does not promise returns or prove a launch is safe.</p></div></div></div></div>`;
 }catch(e){if(route()==='/pro')$('#main').innerHTML=intro('Pro for holders.','Holder service unavailable.')+bundleError(e);}
}

function technologyPreview(){return `<section class="tech-preview" aria-label="Bundle detection technology"><div><span class="eyebrow">BUNDLE TECH, WITH RECEIPTS</span><h2>Read the pattern.<br>Open the proof.</h2><a class="text-button" href="#/technology">Explore our detection ${icon('arrow')}</a></div><div class="tech-preview-grid"><article>${icon('activity')}<strong>Same-slot patterns</strong><p>Distinct transactions. Distinct signing recipients. One observed slot.</p></article><article>${icon('code')}<strong>Execution signals</strong><p>Actual transaction fees, declared priority prices, and available block positions.</p></article><article>${icon('files')}<strong>Traceable evidence</strong><p>Open the exact transactions behind each observation. Missing data stays visible.</p></article></div></section>`;}
function technologyPage(){
 $('#main').innerHTML=intro('Bundle tech. Open by design.','A clear view of the transactions behind the pattern.')+technologyPreview()+`<div class="tech-workflow">${[['01','Read','Fetch a bounded sample of successful mainnet transactions that reference the mint.'],['02','Attribute','Compare exact raw token balances. Count positive changes only for recipient owners who signed.'],['03','Group','Find slots with at least two distinct acquisition transactions and two distinct signing recipients.'],['04','Inspect','Show wallet associations, execution details, coverage gaps, and links to the chain.']].map(([n,title,body])=>`<article><span class="eyebrow">${n}</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div><section class="panel"><div class="panel-header"><h2>What each signal means</h2></div><div class="panel-body"><div class="tech-explainer"><div><span class="local-badge">OBSERVATION</span><h3>Same slot ≠ confirmed bundle</h3><p>A shared slot is observable. Public RPC does not establish that transactions were submitted and executed as an atomic Jito bundle. We do not turn a shared slot into a confirmed-bundle label.</p></div><div><span class="local-badge">EXECUTION</span><h3>Priority fees ≠ Jito tips</h3><p>A compute-unit price instruction declares a priority price in micro-lamports per compute unit. The total transaction fee is a separate RPC value. Neither alone proves a Jito tip, bot, or coordinated owner.</p></div><div><span class="local-badge">RELATIONSHIP</span><h3>Shared source ≠ shared identity</h3><p>An observed SOL transfer can link a source to recipients. Exchanges and shared services can fund unrelated wallets. The report links the transfers without inventing a developer identity.</p></div><div><span class="local-badge">COVERAGE</span><h3>A sample ≠ the full launch</h3><p>Free scans read up to 12 transactions. Pro verifies mint creation and reads a bounded five-slot window, selected current balances, and a small funding lookback. Unknown history remains unknown.</p></div></div><div class="button-row"><a class="primary-button" href="#/">Scan a token ${icon('arrow')}</a><a class="secondary-button" href="#/methodology">Full methodology</a><a class="secondary-button" href="#/pro">Pro for holders</a></div></div></section>`;
}
function techniqueMarkup(r){
 const e=r.execution,rows=e?.transactions||[],groups=r.groups||[];
 return `<section class="tech-evidence"><div class="bundle-map-heading"><div><span class="eyebrow">BUNDLE TECH</span><h4>What the transactions show</h4></div><a class="text-button" href="#/technology">How detection works ${icon('arrow')}</a></div><div class="tech-signal-grid">${[[groups.length+' observed','Same-slot patterns','Two or more acquisition transactions and signing recipients in a shared slot.'],[r.sharedTransfers.length+' observed','Shared SOL sources','Sources transferring SOL to multiple grouped recipients inside the sample.'],[e?e.priorityPriceDeclarations+' / '+rows.length:'Not collected','Priority-price declarations','Declared micro-lamports per compute unit. This is not a Jito-tip count.'],['Not established','Jito bundle confirmation','Public RPC evidence here does not establish atomic bundle submission.']].map(([value,label,body])=>`<article><span>${value}</span><strong>${label}</strong><p>${body}</p></article>`).join('')}</div><details class="execution-details"><summary>Transaction execution evidence ${e?'· '+rows.length+' analyzed':'· rerun this older snapshot to collect'}</summary><p>Positions are zero-based in a returned block. Recent signature scans do not provide block order. Fees are actual total transaction fees; the declared priority price is not the amount paid.</p>${rows.length?`<div class="bundle-wallet-table"><table><thead><tr><th>TRANSACTION / SLOT</th><th>BLOCK POSITION</th><th>TOTAL FEE (LAMPORTS)</th><th>DECLARED PRIORITY (μ-LAMPORTS / CU)</th></tr></thead><tbody>${rows.slice(0,20).map(t=>`<tr><td><a href="https://solscan.io/tx/${esc(t.signature)}" target="_blank" rel="noopener noreferrer"><code>${esc(short(t.signature,6))}</code>${icon('external')}</a><small>Slot ${esc(t.slot)}</small></td><td>${t.blockIndex===null?'Unknown':esc(t.blockIndex)}</td><td>${t.feeLamports===null?'Unknown':esc(t.feeLamports.toLocaleString())}</td><td>${t.priorityFeeMicroLamports===null?(t.instructionsAvailable?'No declaration observed':'Unknown'):esc(t.priorityFeeMicroLamports)}</td></tr>`).join('')}</tbody></table></div><p>Showing ${Math.min(20,rows.length)} of ${rows.length} analyzed execution records.</p>`:'<div class="bundle-empty">No execution records were collected for this snapshot.</div>'}</details></section>`;
}

render();
